import secrets


class AccountService:
    def __init__(self) -> None:
        # email -> {password: str, is_admin: bool}
        self._accounts: dict[str, dict] = {}
        # token -> target email (or None when consumed/invalid)
        self._reset_tokens: dict[str, str] = {}

    def _normalize_email(self, email: str) -> str:
        return email.strip().lower()

    def register(self, email: str, password: str, is_admin: bool = False) -> None:
        if not isinstance(password, str) or len(password) < 8:
            raise ValueError("Password must be at least 8 characters long.")
        key = self._normalize_email(email)
        if key in self._accounts:
            raise ValueError("An account with this email already exists.")
        self._accounts[key] = {"password": password, "is_admin": bool(is_admin)}

    def login(self, email: str, password: str) -> bool:
        key = self._normalize_email(email)
        account = self._accounts.get(key)
        if account is None:
            return False
        if not isinstance(password, str):
            return False
        return account["password"].lower() == password.lower()

    def request_password_reset(self, requester_email: str, target_email: str) -> str:
        requester_key = self._normalize_email(requester_email)
        requester = self._accounts.get(requester_key)
        if requester is None or not requester["is_admin"]:
            raise PermissionError("Only administrators may request password resets.")
        target_key = self._normalize_email(target_email)
        if target_key not in self._accounts:
            raise ValueError("Target account does not exist.")
        token = secrets.token_urlsafe(32)
        self._reset_tokens[token] = target_key
        return token

    def reset_password(self, token: str, new_password: str) -> None:
        if not isinstance(new_password, str) or len(new_password) < 8:
            raise ValueError("Password must be at least 8 characters long.")
        if token not in self._reset_tokens:
            raise ValueError("Invalid or already-used reset token.")
        target_key = self._reset_tokens.pop(token)
        account = self._accounts.get(target_key)
        if account is None:
            # Account was deleted in the meantime; token is now consumed.
            raise ValueError("Invalid or already-used reset token.")
        account["password"] = new_password
